-- =========================================================================
-- Etiquetas QR — fundação de rastreabilidade fim-a-fim por UID
-- Cada etiqueta impressa = 1 linha. UID gerado no front é a PK.
-- Mesma UID viaja em geração → separação → conferência → trânsito → recebimento.
-- =========================================================================

-- 1. Tabela master: 1 linha por etiqueta física
CREATE TABLE IF NOT EXISTS public.etiquetas_qr (
  uid                       text PRIMARY KEY,

  produto_master_id         integer NOT NULL REFERENCES public.produtos_master(id) ON DELETE RESTRICT,
  lote_id                   uuid NULL REFERENCES public.lotes(id) ON DELETE SET NULL,
  embalagem_nome            text NULL,
  quantidade_interna        numeric(12,3) NOT NULL DEFAULT 1,

  -- Snapshots (etiqueta histórica permanece legível mesmo se cadastro mudar)
  produto_nome_snapshot     text NULL,
  lote_codigo_snapshot      text NULL,
  lote_validade_snapshot    date NULL,

  -- Localização
  loja_origem_id            integer NULL REFERENCES public.lojas(id) ON DELETE SET NULL,
  loja_atual_id             integer NULL REFERENCES public.lojas(id) ON DELETE SET NULL,

  -- Status fim-a-fim
  status                    text NOT NULL DEFAULT 'gerada'
                            CHECK (status IN (
                              'gerada','em_separacao','separada',
                              'conferida','em_transito','recebida',
                              'consumida','descartada'
                            )),

  -- Origem
  gerada_por                uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL,
  gerada_at                 timestamptz NULL,
  ultima_movimentacao_id    integer NULL REFERENCES public.movimentacoes(id) ON DELETE SET NULL,

  -- Reposição (nova etiqueta substitui antiga perdida/danificada)
  replaces_uid              text NULL REFERENCES public.etiquetas_qr(uid) ON DELETE SET NULL,
  replaced_by_uid           text NULL REFERENCES public.etiquetas_qr(uid) ON DELETE SET NULL,

  -- Backfill (etiqueta antiga registrada retroativamente ao bipar)
  backfilled                boolean NOT NULL DEFAULT false,

  -- Snapshot do payload original (anti-tamper / forensics)
  qr_payload                jsonb NULL,

  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_produto      ON public.etiquetas_qr(produto_master_id);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_lote         ON public.etiquetas_qr(lote_id);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_loja_atual   ON public.etiquetas_qr(loja_atual_id);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_status       ON public.etiquetas_qr(status);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_gerada_at    ON public.etiquetas_qr(gerada_at DESC NULLS LAST);

COMMENT ON TABLE public.etiquetas_qr IS
  'Source of truth de etiquetas QR físicas. Cada UID = 1 caixa rastreada fim-a-fim (geração → separação → conferência → trânsito → recebimento).';


-- 2. Tabela append-only de eventos (timeline)
CREATE TABLE IF NOT EXISTS public.etiquetas_qr_eventos (
  id                bigserial PRIMARY KEY,
  etiqueta_uid      text NOT NULL REFERENCES public.etiquetas_qr(uid) ON DELETE CASCADE,
  tipo_evento       text NOT NULL,
  etapa             text NOT NULL CHECK (etapa IN (
                       'geracao','separacao','conferencia',
                       'entrada','saida','consumo',
                       'descarte','reposicao','backfill'
                    )),
  status_anterior   text NULL,
  status_novo       text NULL,
  loja_id           integer NULL REFERENCES public.lojas(id) ON DELETE SET NULL,
  usuario_id        uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome      text NULL,
  referencia_tipo   text NULL,
  referencia_id     text NULL,
  metadata          jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_etiquetas_eventos_uid_at  ON public.etiquetas_qr_eventos(etiqueta_uid, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_etiquetas_eventos_etapa   ON public.etiquetas_qr_eventos(etapa, created_at DESC);

COMMENT ON TABLE public.etiquetas_qr_eventos IS
  'Timeline append-only de bips e transições de status por etiqueta. Nunca atualizar nem deletar (audit).';


-- 3. Trigger updated_at
CREATE OR REPLACE FUNCTION public.tg_etiquetas_qr_set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_etiquetas_qr_updated_at ON public.etiquetas_qr;
CREATE TRIGGER trg_etiquetas_qr_updated_at
BEFORE UPDATE ON public.etiquetas_qr
FOR EACH ROW EXECUTE FUNCTION public.tg_etiquetas_qr_set_updated_at();


-- 4. Trigger: ao inserir etiqueta (não-backfill), registrar evento 'geracao'
CREATE OR REPLACE FUNCTION public.tg_etiquetas_qr_log_geracao()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.backfilled = false THEN
    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, metadata
    ) VALUES (
      NEW.uid, 'gerada', 'geracao', NULL, NEW.status,
      NEW.loja_origem_id, NEW.gerada_por, COALESCE(NEW.qr_payload, '{}'::jsonb)
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_etiquetas_qr_log_geracao ON public.etiquetas_qr;
CREATE TRIGGER trg_etiquetas_qr_log_geracao
AFTER INSERT ON public.etiquetas_qr
FOR EACH ROW EXECUTE FUNCTION public.tg_etiquetas_qr_log_geracao();


-- 5. RPC bipar_etiqueta — single source of truth de validação + transição
CREATE OR REPLACE FUNCTION public.bipar_etiqueta(
  p_uid       text,
  p_etapa     text,
  p_contexto  jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_etiqueta            public.etiquetas_qr%ROWTYPE;
  v_user_id             uuid := auth.uid();
  v_user_nome           text;
  v_status_anterior     text;
  v_status_novo         text;
  v_loja_id             integer;
  v_alertas             jsonb := '[]'::jsonb;
  v_referencia_tipo     text;
  v_referencia_id       text;
  v_payload             jsonb;
BEGIN
  -- Etapas válidas
  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa inválida: ' || p_etapa);
  END IF;

  -- Nome do usuário (denormalizado p/ timeline ler sem JOIN)
  SELECT COALESCE(raw_user_meta_data->>'nome', email)
    INTO v_user_nome
    FROM auth.users WHERE id = v_user_id;

  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo';
  v_referencia_id   := p_contexto->>'referencia_id';
  v_payload         := p_contexto->'payload';

  -- Lookup
  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;

  -- ===== BACKFILL =====
  -- Etiqueta inexistente + payload presente → registra retroativamente
  IF NOT FOUND THEN
    IF v_payload IS NULL OR (v_payload->>'p') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta não cadastrada e sem payload para backfill');
    END IF;

    INSERT INTO public.etiquetas_qr (
      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
      loja_origem_id, loja_atual_id, status, backfilled, qr_payload
    ) VALUES (
      p_uid,
      (v_payload->>'p')::integer,
      NULLIF(v_payload->>'l','')::uuid,
      v_payload->>'n',
      COALESCE(NULLIF(v_payload->>'q','')::numeric, 1),
      NULL, v_loja_id,
      CASE p_etapa
        WHEN 'separacao'   THEN 'separada'
        WHEN 'conferencia' THEN 'conferida'
        WHEN 'entrada'     THEN 'recebida'
        WHEN 'saida'       THEN 'em_transito'
        WHEN 'consumo'     THEN 'consumida'
        WHEN 'descarte'    THEN 'descartada'
      END,
      true,
      v_payload
    )
    RETURNING * INTO v_etiqueta;

    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');

    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', NULL,
      'status_novo', v_etiqueta.status,
      'alertas', v_alertas,
      'backfilled', true
    );
  END IF;

  -- ===== Etiqueta encontrada — validar transição =====
  v_status_anterior := v_etiqueta.status;

  IF v_etiqueta.status = 'descartada' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'erro', 'Etiqueta descartada' ||
              CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL
                   THEN ' (substituída por ' || v_etiqueta.replaced_by_uid || ')'
                   ELSE ''
              END,
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  -- Mapa de transições válidas. NULL = transição inválida (duplicata ou fora de ordem)
  v_status_novo := CASE p_etapa
    WHEN 'separacao' THEN
      CASE WHEN v_etiqueta.status IN ('gerada','recebida','em_separacao') THEN 'separada'
           ELSE NULL END
    WHEN 'conferencia' THEN
      CASE WHEN v_etiqueta.status IN ('separada','gerada','recebida') THEN 'conferida'
           ELSE NULL END
    WHEN 'saida' THEN
      CASE WHEN v_etiqueta.status IN ('conferida','separada','gerada') THEN 'em_transito'
           ELSE NULL END
    WHEN 'entrada' THEN
      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','conferida') THEN 'recebida'
           WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
           ELSE NULL END
    WHEN 'consumo'   THEN 'consumida'
    WHEN 'descarte'  THEN 'descartada'
  END;

  IF v_status_novo IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'erro', format('Etiqueta %s já está com status "%s" — bip duplicado nesta etapa',
                     p_uid, v_status_anterior),
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  -- Alerta de validade (não bloqueia, mas avisa)
  IF v_etiqueta.lote_validade_snapshot IS NOT NULL
     AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN
    v_alertas := v_alertas || jsonb_build_array(
      format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))
    );
  END IF;

  -- Atualizar etiqueta
  UPDATE public.etiquetas_qr SET
    status        = v_status_novo,
    loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
  WHERE uid = p_uid
  RETURNING * INTO v_etiqueta;

  -- Registrar evento
  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
  ) VALUES (
    p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo,
    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
    p_contexto - 'payload'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'etiqueta', to_jsonb(v_etiqueta),
    'status_anterior', v_status_anterior,
    'status_novo', v_status_novo,
    'alertas', v_alertas,
    'backfilled', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.bipar_etiqueta(text, text, jsonb) TO authenticated;

COMMENT ON FUNCTION public.bipar_etiqueta IS
  'Validação atômica de bip: parse contexto, valida transição, atualiza etiqueta, registra evento. Retorna {ok, etiqueta, status_anterior, status_novo, alertas, backfilled, erro}.';


-- 6. RPC reposicao_etiqueta — gera nova UID que substitui uma antiga
CREATE OR REPLACE FUNCTION public.reposicao_etiqueta(
  p_uid_antiga  text,
  p_uid_nova    text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_antiga      public.etiquetas_qr%ROWTYPE;
  v_user_id     uuid := auth.uid();
  v_user_nome   text;
BEGIN
  SELECT * INTO v_antiga FROM public.etiquetas_qr WHERE uid = p_uid_antiga;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta antiga não encontrada');
  END IF;
  IF v_antiga.status = 'descartada' THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta antiga já descartada');
  END IF;

  SELECT COALESCE(raw_user_meta_data->>'nome', email)
    INTO v_user_nome FROM auth.users WHERE id = v_user_id;

  -- Cria nova etiqueta com mesmos atributos físicos da antiga
  INSERT INTO public.etiquetas_qr (
    uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
    produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
    loja_origem_id, loja_atual_id, status, gerada_por, gerada_at,
    replaces_uid, qr_payload
  ) VALUES (
    p_uid_nova, v_antiga.produto_master_id, v_antiga.lote_id,
    v_antiga.embalagem_nome, v_antiga.quantidade_interna,
    v_antiga.produto_nome_snapshot, v_antiga.lote_codigo_snapshot, v_antiga.lote_validade_snapshot,
    v_antiga.loja_origem_id, v_antiga.loja_atual_id, 'gerada', v_user_id, now(),
    p_uid_antiga, v_antiga.qr_payload
  );

  -- Marca antiga como descartada apontando pra nova
  UPDATE public.etiquetas_qr
     SET status = 'descartada', replaced_by_uid = p_uid_nova
   WHERE uid = p_uid_antiga;

  -- Evento na antiga
  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    usuario_id, usuario_nome, metadata
  ) VALUES (
    p_uid_antiga, 'substituida', 'reposicao', v_antiga.status, 'descartada',
    v_user_id, v_user_nome, jsonb_build_object('replaced_by', p_uid_nova)
  );

  -- Evento na nova (geração via reposição, em adição ao trigger de geração)
  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    usuario_id, usuario_nome, metadata
  ) VALUES (
    p_uid_nova, 'reposicao', 'reposicao', NULL, 'gerada',
    v_user_id, v_user_nome, jsonb_build_object('replaces', p_uid_antiga)
  );

  RETURN jsonb_build_object('ok', true, 'uid_nova', p_uid_nova, 'uid_antiga', p_uid_antiga);
END;
$$;

GRANT EXECUTE ON FUNCTION public.reposicao_etiqueta(text, text) TO authenticated;


-- 7. View de timeline pronta pro frontend
CREATE OR REPLACE VIEW public.view_etiqueta_timeline AS
SELECT
  e.uid,
  e.produto_master_id,
  e.produto_nome_snapshot,
  e.lote_id,
  e.lote_codigo_snapshot,
  e.lote_validade_snapshot,
  e.embalagem_nome,
  e.quantidade_interna,
  e.status,
  e.loja_origem_id,
  l_origem.nome AS loja_origem_nome,
  e.loja_atual_id,
  l_atual.nome  AS loja_atual_nome,
  e.gerada_at,
  e.gerada_por,
  e.replaces_uid,
  e.replaced_by_uid,
  e.backfilled,
  e.created_at,
  e.updated_at,
  COALESCE(
    (SELECT jsonb_agg(jsonb_build_object(
        'id',              ev.id,
        'tipo_evento',     ev.tipo_evento,
        'etapa',           ev.etapa,
        'status_anterior', ev.status_anterior,
        'status_novo',     ev.status_novo,
        'loja_id',         ev.loja_id,
        'loja_nome',       lj.nome,
        'usuario_nome',    ev.usuario_nome,
        'referencia_tipo', ev.referencia_tipo,
        'referencia_id',   ev.referencia_id,
        'metadata',        ev.metadata,
        'created_at',      ev.created_at
      ) ORDER BY ev.created_at)
     FROM public.etiquetas_qr_eventos ev
     LEFT JOIN public.lojas lj ON lj.id = ev.loja_id
     WHERE ev.etiqueta_uid = e.uid),
    '[]'::jsonb
  ) AS eventos
FROM public.etiquetas_qr e
LEFT JOIN public.lojas l_origem ON l_origem.id = e.loja_origem_id
LEFT JOIN public.lojas l_atual  ON l_atual.id  = e.loja_atual_id;

GRANT SELECT ON public.view_etiqueta_timeline TO authenticated;


-- 8. RLS
ALTER TABLE public.etiquetas_qr        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.etiquetas_qr_eventos ENABLE ROW LEVEL SECURITY;

-- SELECT aberto para autenticados (rastreabilidade interna)
DROP POLICY IF EXISTS "etiquetas_qr_select_authenticated" ON public.etiquetas_qr;
CREATE POLICY "etiquetas_qr_select_authenticated"
  ON public.etiquetas_qr FOR SELECT
  TO authenticated USING (true);

DROP POLICY IF EXISTS "etiquetas_qr_eventos_select_authenticated" ON public.etiquetas_qr_eventos;
CREATE POLICY "etiquetas_qr_eventos_select_authenticated"
  ON public.etiquetas_qr_eventos FOR SELECT
  TO authenticated USING (true);

-- INSERT direto: apenas para impressão (LabelPrinting). Validação de payload no front.
DROP POLICY IF EXISTS "etiquetas_qr_insert_authenticated" ON public.etiquetas_qr;
CREATE POLICY "etiquetas_qr_insert_authenticated"
  ON public.etiquetas_qr FOR INSERT
  TO authenticated WITH CHECK (auth.uid() IS NOT NULL);

-- UPDATE / DELETE direto bloqueados — única via é via RPC SECURITY DEFINER
-- INSERT em eventos também é apenas via RPC (sem policy = bloqueado)

