  if (!payload.uid) {
    playErrorSound();
    toast.error("Etiqueta sem UID — não rastreável");
    return;
  }
  if (uidsLidosRef.current.has(payload.uid)) {
    playErrorSound();
    toast.error("Caixa já bipada nesta chegada");
    if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
    return;
  }

  await marcarChegadaIniciada();

  // RPC: valida transição em_transito → recebida
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
    p_uid: payload.uid,
    p_etapa: "entrada",
    p_contexto: {
      loja_id: lojaDestinoId,
      referencia_tipo: "requisicao_chegada",
      referencia_id: String(requisicaoId),
      payload,
    },
  });
  if (rpcErr) {
    playErrorSound();
    toast.error(`Falha no bip: ${rpcErr.message}`);
    return;
  }
  const result = rpcRaw as {
    ok: boolean; erro?: string;
    etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; lote_id?: string | null; quantidade_interna?: number; embalagem_nome?: string | null };
    alertas?: string[];
  };
  if (!result?.ok || !result.etiqueta) {
    playErrorSound();
    toast.error(formatBipError(result?.erro, "entrada"));
    if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
    return;
  }
  (result.alertas ?? []).forEach((a) => {
    playWarningSound();
    toast.warning(a);
  });

  const et = result.etiqueta;
  const qty = Number(et.quantidade_interna ?? payload.qty ?? 1);
  const target = localItems.find((i) => i.masterId === et.produto_master_id);
  if (!target) {
    playWarningSound();
    if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
    toast.warning(`${et.produto_nome_snapshot || `#${et.produto_master_id}`} NÃO está nesta requisição`);
    uidsLidosRef.current.add(payload.uid);
    return;
  }

  // Soma à quantidade_recebida atual
  const baseAtual = Number(target.quantidade_recebida || "0") || 0;
  const novaQtdNum = baseAtual + qty;

  // INSERT movimentacao (entrada de estoque)
  const { data: { user } } = await supabase.auth.getUser();
  const { data: estoqueAtual } = await supabase
    .from("estoque")
    .select("quantidade_atual")
    .eq("produto_master_id", et.produto_master_id)
    .eq("loja_id", lojaDestinoId)
    .maybeSingle();
  const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
  const nova = anterior + qty;

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error: movErr } = await (supabase.from("movimentacoes") as any).insert({
    produto_master_id: et.produto_master_id,
    tipo_movimentacao: "entrada",
    quantidade: qty,
    quantidade_anterior: anterior,
    quantidade_nova: nova,
    motivo: "recebimento",
    observacoes: `Chegada req #${requisicaoId} — UID ${payload.uid}`,
    data_movimentacao: new Date().toISOString(),
    loja_id: lojaDestinoId,
    lote_id: et.lote_id,
    etiqueta_qr_uid: payload.uid,
  });
  if (movErr) {
    playErrorSound();
    toast.error(`Erro ao registrar entrada: ${movErr.message}`);
    return;
  }

  // Atualiza linha da requisição
  const { error: upErr } = await updateItemRow(target.id, String(novaQtdNum), "bip", user?.id ?? null);
  if (upErr) {
    playErrorSound();
    toast.error(`Erro ao salvar conferência: ${upErr.message}`);
    return;
  }

  playSuccessSound();
  if (navigator.vibrate) navigator.vibrate(80);
  toast.success(`${target.nome_produto} +${qty} un (${et.embalagem_nome || "Un"})`);

  setLocalItems((prev) =>
    prev.map((i) => i.id === target.id
      ? { ...i, quantidade_recebida: String(novaQtdNum), recebida_via: "bip", recebida_at: new Date().toISOString() }
      : i),
  );
  setBipsLog((prev) => [
    { itemId: target.id, uid: payload.uid, qty, embalagem: et.embalagem_nome ?? null, bipadoAt: Date.now() },
    ...prev,
  ]);
  uidsLidosRef.current.add(payload.uid);
};

const scanner = useEtiquetaScanner({
  enabled: isOpen,
  onScan: handleBip,
  cameraElementId: "chegada-qr-reader",
  onInvalid: () => toast.error("QR ilegível"),
  onDuplicate: () => {
    playErrorSound();
    toast.error("Esta etiqueta já foi bipada");
  },
});

const askManual = (item: ChegadaItem) => {
  const restante = Math.max(0, item.quantidade_solicitada - (Number(item.quantidade_recebida || "0") || 0));
  setManual({
    open: true,
    item,
    quantidade: String(restante > 0 ? restante : item.quantidade_solicitada),
  });
};

const confirmManual = async () => {
  if (!manual.item) return;
  const qty = Number(manual.quantidade);
  if (!Number.isFinite(qty) || qty < 0) {
    toast.error("Quantidade inválida");
    return;
  }
  await marcarChegadaIniciada();
  const { data: { user } } = await supabase.auth.getUser();
  const { error } = await updateItemRow(manual.item.id, String(qty), "manual", user?.id ?? null);
  if (error) {
    toast.error(`Erro ao salvar: ${error.message}`);
    return;
  }
  setLocalItems((prev) =>
    prev.map((i) => i.id === manual.item!.id
      ? { ...i, quantidade_recebida: String(qty), recebida_via: "manual", recebida_at: new Date().toISOString() }
      : i),
  );
  setManual({ open: false, quantidade: "" });
  toast.success(`${manual.item.nome_produto}: ${qty} un (manual)`);
};

const concluir = async () => {
  setConcluindo(true);
  const { data: { user } } = await supabase.auth.getUser();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { error } = await (supabase.from("requisicoes") as any)
    .update({
      chegada_concluida_at: new Date().toISOString(),
      chegada_concluida_por: user?.id ?? null,
    })
    .eq("id", requisicaoId);
  setConcluindo(false);
  if (error) {
    toast.error(`Erro ao concluir: ${error.message}`);
    return;
  }
  toast.success("Chegada concluída.");
  onConcluida?.();
  onClose();
};
